        if not self.verify_code(comp, code):
            self._audit(now, "bad-code", comp, "")
            raise BadCode(comp)
        parcel = self.parcels.pop(comp)
        self._audit(now, "release", comp, parcel["ref"])
        log.info("released %s from %s", parcel["ref"], comp)
        return parcel["ref"]

