        """The smallest free compartment that fits the parcel; ties go to the lowest id."""
        need = SIZE_RANK[size]
        best = None
        for comp, sz in sorted(self.sizes.items()):
            if comp in self.parcels or SIZE_RANK[sz] < need:
                continue
